// =============================================================================
// Lovable Vibe: Midnight 00:00 UTC Pairing Auto-Reset Hook
// Reverts all project pairings back to original owner at 00:00 UTC daily
// =============================================================================
(function() {
  function hasCrossedMidnightUtc(timestamp) {
    if (!timestamp) return true;
    const pairedDate = new Date(Number(timestamp));
    if (isNaN(pairedDate.getTime())) return true;
    const now = new Date();
    const pairedUtc = `${pairedDate.getUTCFullYear()}-${pairedDate.getUTCMonth()}-${pairedDate.getUTCDate()}`;
    const nowUtc = `${now.getUTCFullYear()}-${now.getUTCMonth()}-${now.getUTCDate()}`;
    return (pairedUtc !== nowUtc && now.getTime() > pairedDate.getTime());
  }

  function checkAndResetMidnightUtcPairings() {
    try {
      const keysToRemove = [];

      for (let i = 0; i < window.localStorage.length; i++) {
        const k = window.localStorage.key(i);
        if (!k) continue;

        if (k.startsWith('lz_paired_time_') || k.startsWith('lastzone_paired_time_')) {
          const t = Number(window.localStorage.getItem(k) || 0);
          if (hasCrossedMidnightUtc(t)) {
            const base = k.replace(/^lz_paired_time_|^lastzone_paired_time_/, '');
            keysToRemove.push(
              k,
              'lz_paired_' + base,
              'lastzone_paired_' + base,
              'lz_paired_email_' + base,
              'lastzone_paired_email_' + base
            );
          }
        }
      }

      if (keysToRemove.length > 0) {
        keysToRemove.forEach(k => {
          try { window.localStorage.removeItem(k); } catch (_) {}
        });
        console.log('[LOVABLE VIBE] 🌙 00:00 UTC reached! All project pairings reverted to original owners.');
        window.postMessage({ type: 'LASTZONE_DATA_SYNC' }, '*');
      }
    } catch (_) {}
  }

  try {
    const origSetItem = window.localStorage.setItem.bind(window.localStorage);
    window.localStorage.setItem = function(key, val) {
      origSetItem(key, val);
      if (typeof key === 'string' && (key.startsWith('lz_paired_') || key.startsWith('lastzone_paired_')) && !key.includes('_time_') && !key.includes('_email_')) {
        const timeKey = key.startsWith('lz_paired_') ? key.replace('lz_paired_', 'lz_paired_time_') : key.replace('lastzone_paired_', 'lastzone_paired_time_');
        if (!window.localStorage.getItem(timeKey)) {
          origSetItem(timeKey, String(Date.now()));
        }
      }
    };
  } catch (_) {}

  checkAndResetMidnightUtcPairings();
  setInterval(checkAndResetMidnightUtcPairings, 30000); // Check every 30 seconds
})();

